import type {
  AnnotationExecutionMode,
  DeploymentStatus,
  ReviewTrackCandidate,
  SegmentState,
} from './types'

interface AnnotationOptionsInput {
  videoId: string
  segmentId: number
  mode: AnnotationExecutionMode
  reviewCandidates?: ReviewTrackCandidate[]
}

/**
 * Carry only user-created boxes into a re-run's semantic stage. Model tracks
 * are regenerated by YOLO/ByteTrack and must not be copied from stale output.
 */
export function buildReviewTrackCandidates(segment: SegmentState): ReviewTrackCandidate[] {
  const annotation = segment.humanAnnotation
  if (!annotation) return []

  const manualPersonIds = new Map(
    (annotation.persons || [])
      .filter(person => person._className === 'manual')
      .map(person => [person.trackId, person.personId] as const),
  )
  const manualObjectIds = new Set(
    (annotation.objects || [])
      .filter(object => (object as unknown as { _className?: string })._className === 'manual')
      .map(object => object.trackId),
  )
  const candidates = new Map<string, ReviewTrackCandidate>()

  for (const frame of annotation.frames || []) {
    for (const observation of frame.observations || []) {
      const isManual = observation.source === 'manual'
        || (observation.entityType === 'person' && manualPersonIds.has(observation.trackId))
        || (observation.entityType === 'object' && manualObjectIds.has(observation.trackId))
      if (!isManual) continue
      const key = `${observation.entityType}:${observation.trackId}`
      if (candidates.has(key)) continue
      candidates.set(key, {
        trackId: observation.trackId,
        entityType: observation.entityType,
        className: observation.className,
        bbox: observation.bbox,
        timestamp: frame.timestamp,
        imageWidth: frame.imageWidth,
        imageHeight: frame.imageHeight,
        personId: observation.entityType === 'person'
          ? manualPersonIds.get(observation.trackId) || null
          : undefined,
      })
    }
  }
  return [...candidates.values()]
}

/**
 * Build per-job Worker options.
 *
 * LocateAnything stays installed and globally available, but ordinary
 * annotation jobs opt out explicitly. A precision job opts in for only the
 * selected segment.
 */
export function buildAnnotationOptions({
  videoId,
  segmentId,
  mode,
  reviewCandidates = [],
}: AnnotationOptionsInput): Record<string, unknown> {
  return {
    sample_fps: 0.5,
    tracking_fps: 3,
    ontology: {},
    video_id: videoId,
    segment_id: segmentId,
    review_candidates: reviewCandidates,
    providers: {
      locate_anything: mode === 'precision',
    },
  }
}

export function precisionAvailabilityError(
  deployment: DeploymentStatus,
): string | null {
  if (deployment.mode !== 'enhanced') {
    return 'Precise Locate requires enhanced deployment mode. Enable and prepare enhanced mode in Settings first.'
  }
  if (deployment.enhancedSetup.status !== 'ready') {
    return deployment.enhancedSetup.error
      || deployment.enhancedSetup.providerReason
      || 'LocateAnything is not ready. Complete enhanced model preparation in Settings first.'
  }
  return null
}
